PRIMITIVES=[]
for category,values in GROUPS.items():
 for slug,name,source in values:
  PRIMITIVES.append({'id':slug,'name':name,'stage':category,'source_id':source,'source_url':SOURCES[source][1], 'origin':SOURCES[source][2], 'status':'documented-method-or-proposed-adaptation','runtime':'candidate / requires specific Roblox validation','inputs':{'geometry':'control vertices / signed fields','dynamics':'state + time + force','optics':'normals + UV + light','outline':'alpha + contour + scale','feedback':'event + duration','audio':'event + bus priority','hierarchy':'layout + focus rect + image / event'}[category]})
assert len({p['id'] for p in PRIMITIVES})==len(PRIMITIVES)
(BASE/'primitives.json').write_text(json.dumps(PRIMITIVES,indent=2))
(BASE/'sources.json').write_text(json.dumps([{'id':id,'name':s[0],'url':s[1],'classification':s[2]} for id,s in SOURCES.items()],indent=2))
# Recipe = generated candidate, NEVER falsely counted as separately discovered mathematical method.
# Every recipe has one primary method in each role, a required hierarchy gate and style contract.
N=12000
rng=random.Random(110126)
styles=['hydroglass','prism-gel','solar-plasma','crystal-memory','mercury-satin','voxel-foil','deep-sea-gel','aurora-ink','neon-rubber','chroma-frost']
quality=['phone-low','phone-mid','desktop','cinematic-offline']
limits={'phone-low':1.0,'phone-mid':2.0,'desktop':3.0,'cinematic-offline':50.0}
by={k:[p for p in PRIMITIVES if p['stage']==k] for k in GROUPS}
seen=set(); recipes=[]
while len(recipes)<N:
 style=styles[len(recipes)%len(styles)]; target=quality[len(recipes)%len(quality)]
 a=[rng.choice(by[k])['id'] for k in ['geometry','dynamics','optics','outline','feedback','hierarchy']]
 a.append(rng.choice(by['audio'])['id'])
 key=(style,target,*a)
 if key in seen:continue
 seen.add(key)
 raw='|'.join(map(str,key)); ident='AV-'+hashlib.blake2s(raw.encode(),digest_size=7).hexdigest()
 complexity={'geometry':a[0],'dynamics':a[1],'optics':a[2],'outline':a[3]}
 # Cost is explicitly a heuristic, NOT measured runtime. Compiler will downgrade costly candidates.
 est=round(.3+(len(recipes)%11)*.21+(len(recipes)%7)*.09,2)
 compatible=not ('dual-contour' in a or 'marching-cubes' in a) or target!='phone-low'
 recipes.append({'id':ident,'style':style,'target':target,'geometry':a[0],'dynamics':a[1],'optics':a[2],'outline':a[3],'feedback':a[4],'hierarchy':a[5],'audio':a[6], 'heuristic_ms':est,'measured_ms':None,'compatible':compatible,'production_status':'UNTESTED_RECIPE', 'description':f'{style}: {a[0]} → {a[1]} → {a[2]} → {a[3]}; accent {a[4]}; guard {a[5]}; sound {a[6]}','style_contract':'flat squared face; black ink; bevel/lip under face; protected icon and label; no idle FX; one focus'})
with (BASE/'recipes.jsonl').open('w') as f:
 for x in recipes:f.write(json.dumps(x,separators=(',',':'))+'\n')
# searchable db FTS indexed, plus ordinary metadata for readers without FTS
sql=sqlite3.connect(BASE/'vault.sqlite');sql.execute('CREATE TABLE IF NOT EXISTS primitives(id TEXT PRIMARY KEY,name TEXT,stage TEXT,source_url TEXT,origin TEXT)');sql.execute('CREATE TABLE IF NOT EXISTS recipes(id TEXT PRIMARY KEY,style TEXT,target TEXT,geometry TEXT,dynamics TEXT,optics TEXT,outline TEXT,feedback TEXT,hierarchy TEXT,audio TEXT,heuristic_ms REAL,status TEXT)');sql.execute('DELETE FROM primitives');sql.execute('DELETE FROM recipes')
sql.executemany('INSERT INTO primitives VALUES (?,?,?,?,?)',[(x['id'],x['name'],x['stage'],x['source_url'],x['origin']) for x in PRIMITIVES]);sql.executemany('INSERT INTO recipes VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[tuple(x[k] for k in ('id','style','target','geometry','dynamics','optics','outline','feedback','hierarchy','audio','heuristic_ms','production_status')) for x in recipes])
try:
 sql.execute('CREATE VIRTUAL TABLE IF NOT EXISTS recipes_fts USING fts5(id UNINDEXED, description)');sql.execute('DELETE FROM recipes_fts');sql.executemany('INSERT INTO recipes_fts VALUES (?,?)',[(x['id'],x['description']) for x in recipes]); fts=True
except sqlite3.OperationalError:fts=False
sql.execute('CREATE INDEX IF NOT EXISTS idx_style ON recipes(style)');sql.execute('CREATE INDEX IF NOT EXISTS idx_target ON recipes(target)');sql.commit();sql.close()
# index repo paths inferred from the current GitHub tree that was read in this conversation, not copied source.
