(BASE/'repo_manifest.json').write_text(json.dumps({'repository':'jewdah-afk/aaa-kit','ref':'main','inspected_paths':repo_paths,'note':'Paths verified via GitHub API tree and selected documents, not a complete source-code mirror.'},indent=2))
manifest={'schema':'aaa-kit-algorithm-vault-v1','primitives':len(PRIMITIVES),'generated_recipes':len(recipes),'externally_sourced_method_families':len([p for p in PRIMITIVES if p['source_id'] not in ['REPO','PACK']]),'repo_method_families':len([p for p in PRIMITIVES if p['source_id']=='REPO']),'uploaded-pack_method_families':len([p for p in PRIMITIVES if p['source_id']=='PACK']),'source_catalog':len(SOURCES),'fts_enabled':fts,'claims':'Primitives are curated method families; recipes are synthetic combinations, not 12,000 unique discoveries or validated Roblox features.','status':'Generated locally. No GitHub commit.'}
(BASE/'manifest.json').write_text(json.dumps(manifest,indent=2));print(manifest)
